files..gemini/settings.json:
{
  "hooks": {
    "AfterAgent": [
      {
        "hooks": [
          {
            "command": "lonca hook --harness gemini --fail-open",
            "type": "command"
          }
        ],
        "matcher": "*"
      }
    ],
    "AfterTool": [
      {
        "hooks": [
          {
            "command": "lonca hook --harness gemini",
            "type": "command"
          }
        ],
        "matcher": "*"
      }
    ],
    "BeforeTool": [
      {
        "hooks": [
          {
            "command": "lonca hook --harness gemini",
            "type": "command"
          }
        ],
        "matcher": "*"
      }
    ],
    "SessionStart": [
      {
        "hooks": [
          {
            "command": "lonca hook --harness gemini",
            "type": "command"
          }
        ],
        "matcher": "*"
      }
    ]
  },
  "mcpServers": {
    "lonca": {
      "args": [
        "mcp"
      ],
      "command": "lonca",
      "cwd": "/w",
      "env": {
        "LONCA_SOCKET": "/s/lonca.sock",
        "LONCA_WORKSPACE": "/w"
      },
      "trust": true
    }
  }
}
